import { path } from '@servicenow/sdk-build-core'
import { createTestContext, getMergedRecordUpdates } from './test-utils'

describe('Complex Object Determinism Test Suite', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, 'project') })
    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())
    describe('Deterministic Complex Object (no $id or co_type_name)', () => {
        test('Fluent → XML: Should generate deterministic co_type_name as FD<variable_sys_id>', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'flow-complex-object-deterministic.now.ts', 'create')

            // Verify flow variable was created
            expect(merged['sys_hub_flow_variable']).toHaveLength(1)
            const flowVariable = merged['sys_hub_flow_variable'][0]
            expect(flowVariable.element).toBe('employee')
            expect(flowVariable.label).toBe('Employee')

            // Extract variable sys_id
            const varSysId = flowVariable.sys_id

            // Verify complex object was created with deterministic co_type_name
            expect(merged['sys_complex_object']).toHaveLength(1)
            const complexObject = merged['sys_complex_object'][0]

            // co_type_name should be FD<variable_sys_id>
            const expectedCoTypeName = `FD${varSysId}`
            expect(complexObject.name).toBe(expectedCoTypeName)
            expect(complexObject.namespace).toBe('FlowDesigner')
            expect(complexObject.type).toBe('complex_object_schema')

            // Verify serialized_content contains the schema
            const schema = JSON.parse(complexObject.serialized_content)
            const schemaKey = `FlowDesigner:${expectedCoTypeName}`
            expect(schema[schemaKey]).toBeDefined()
            expect(schema[schemaKey].name).toBe('String')
            expect(schema[schemaKey].age).toBe('Integer')
            expect(schema[schemaKey].department).toBe('String')

            // Verify attributes contain the deterministic co_type_name
            expect(flowVariable.attributes).toContain(`co_type_name=${expectedCoTypeName}`)
        })

        test('XML → Fluent: Should NOT include $id and co_type_name (deterministic)', async () => {
            const project = ctx.createProject()

            // First, generate XML from Fluent
            const merged = await getMergedRecordUpdates(project, 'flow-complex-object-deterministic.now.ts', 'create')
            const flowVariable = merged['sys_hub_flow_variable'][0]
            const varSysId = flowVariable.sys_id
            const expectedCoTypeName = `FD${varSysId}`

            // Create a mock XML with deterministic co_type_name
            const xmlContent = `<?xml version="1.0"?>
<record_update>
  <sys_hub_flow action="INSERT_OR_UPDATE">
    <sys_id>deterministic_complex_object_flow</sys_id>
    <name>Flow with Deterministic Complex Object</name>
  </sys_hub_flow>
  <sys_hub_flow_variable action="INSERT_OR_UPDATE">
    <sys_id>${varSysId}</sys_id>
    <element>employee</element>
    <label>Employee</label>
    <internal_type>string</internal_type>
    <attributes>co_type_name=${expectedCoTypeName},uiType=object</attributes>
    <model>deterministic_complex_object_flow</model>
    <model_table>sys_hub_flow</model_table>
  </sys_hub_flow_variable>
  <sys_complex_object action="INSERT_OR_UPDATE">
    <sys_id>complex_obj_sys_id</sys_id>
    <name>${expectedCoTypeName}</name>
    <namespace>FlowDesigner</namespace>
    <serialized_content>{"FlowDesigner:${expectedCoTypeName}":{"name":"String","name.$field_facets":{"SimpleMapFacet":"{\\"uiType\\":\\"string\\",\\"label\\":\\"Employee Name\\"}"},"age":"Integer","age.$field_facets":{"SimpleMapFacet":"{\\"uiType\\":\\"integer\\",\\"label\\":\\"Employee Age\\"}"},"department":"String","department.$field_facets":{"SimpleMapFacet":"{\\"uiType\\":\\"string\\",\\"label\\":\\"Department\\"}"}},"FlowDesigner:${expectedCoTypeName}.$type_facets":{"SimpleMapFacet":"{\\"uiType\\":\\"object\\",\\"label\\":\\"Employee\\"}"}}</serialized_content>
  </sys_complex_object>
</record_update>`

            // Transform XML back to Fluent
            const { changedFiles } = await project.transform({
                path: 'sys_hub_flow_deterministic_complex_object_flow.xml',
                content: xmlContent,
            })

            // May generate 1 or 2 files (flow + potentially complex object)
            expect(changedFiles.length).toBeGreaterThanOrEqual(1)
            const flowFile = changedFiles.find((f) => f.getName().includes('sys_hub_flow'))
            expect(flowFile).toBeDefined()
            const content = flowFile!.getContent()

            // Verify FlowObject exists
            expect(content).toContain('FlowObject({')
            expect(content).toContain('employee:')

            // Extract just the FlowObject section to check for $id and co_type_name
            const fluentLines = content.split('\n')
            const employeeLineIndex = fluentLines.findIndex((line) => line.includes('employee: FlowObject'))
            const flowObjectSection = fluentLines.slice(employeeLineIndex, employeeLineIndex + 20).join('\n')

            // Verify $id and co_type_name are NOT present in FlowObject (deterministic)
            expect(flowObjectSection).not.toContain('$id:')
            expect(flowObjectSection).not.toContain('co_type_name:')

            // Verify fields are present
            expect(content).toContain('name: StringColumn')
            expect(content).toContain('age: IntegerColumn')
            expect(content).toContain('department: StringColumn')
        })
    })

    describe('Non-Deterministic Complex Object (with $id and co_type_name)', () => {
        test('Fluent → XML: Should use provided $id and co_type_name', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(
                project,
                'flow-complex-object-non-deterministic.now.ts',
                'create'
            )

            // Verify flow variable was created
            expect(merged['sys_hub_flow_variable']).toHaveLength(1)
            const flowVariable = merged['sys_hub_flow_variable'][0]
            expect(flowVariable.element).toBe('customer')
            expect(flowVariable.label).toBe('Customer')

            // Verify complex object was created with provided co_type_name
            expect(merged['sys_complex_object']).toHaveLength(1)
            const complexObject = merged['sys_complex_object'][0]

            // co_type_name should be the custom one, NOT FD<variable_sys_id>
            expect(complexObject.name).toBe('CustomCustomerType123')
            expect(complexObject.sys_id).toBe('custom_complex_object_id_from_ui')
            expect(complexObject.namespace).toBe('FlowDesigner')
            expect(complexObject.type).toBe('complex_object_schema')

            // Verify serialized_content contains the schema
            const schema = JSON.parse(complexObject.serialized_content)
            const schemaKey = 'FlowDesigner:CustomCustomerType123'
            expect(schema[schemaKey]).toBeDefined()
            expect(schema[schemaKey].firstName).toBe('String')
            expect(schema[schemaKey].lastName).toBe('String')
            expect(schema[schemaKey].email).toBe('String')
            expect(schema[schemaKey].age).toBe('Integer')
            expect(schema[schemaKey].isActive).toBe('Boolean')

            // Verify attributes contain the custom co_type_name
            expect(flowVariable.attributes).toContain('co_type_name=CustomCustomerType123')
        })

        test('XML → Fluent: Should include $id and co_type_name (non-deterministic)', async () => {
            const project = ctx.createProject()

            // Create a mock XML with non-deterministic co_type_name
            const xmlContent = `<?xml version="1.0"?>
<record_update>
  <sys_hub_flow action="INSERT_OR_UPDATE">
    <sys_id>non_deterministic_complex_object_flow</sys_id>
    <name>Flow with Non-Deterministic Complex Object</name>
  </sys_hub_flow>
  <sys_hub_flow_variable action="INSERT_OR_UPDATE">
    <sys_id>some_variable_sys_id_123</sys_id>
    <element>customer</element>
    <label>Customer</label>
    <internal_type>string</internal_type>
    <attributes>co_type_name=CustomCustomerType123,uiType=object</attributes>
    <model>non_deterministic_complex_object_flow</model>
    <model_table>sys_hub_flow</model_table>
  </sys_hub_flow_variable>
  <sys_complex_object action="INSERT_OR_UPDATE">
    <sys_id>custom_complex_object_id_from_ui</sys_id>
    <name>CustomCustomerType123</name>
    <namespace>FlowDesigner</namespace>
    <serialized_content>{"FlowDesigner:CustomCustomerType123":{"firstName":"String","firstName.$field_facets":{"SimpleMapFacet":"{\\"uiType\\":\\"string\\",\\"label\\":\\"First Name\\",\\"mandatory\\":\\"true\\"}"},"lastName":"String","lastName.$field_facets":{"SimpleMapFacet":"{\\"uiType\\":\\"string\\",\\"label\\":\\"Last Name\\",\\"mandatory\\":\\"true\\"}"},"email":"String","email.$field_facets":{"SimpleMapFacet":"{\\"uiType\\":\\"string\\",\\"label\\":\\"Email Address\\"}"},"age":"Integer","age.$field_facets":{"SimpleMapFacet":"{\\"uiType\\":\\"integer\\",\\"label\\":\\"Age\\"}"},"isActive":"Boolean","isActive.$field_facets":{"SimpleMapFacet":"{\\"uiType\\":\\"boolean\\",\\"label\\":\\"Active Status\\",\\"default_value\\":\\"true\\"}"}},"FlowDesigner:CustomCustomerType123.$type_facets":{"SimpleMapFacet":"{\\"uiType\\":\\"object\\",\\"label\\":\\"Customer\\"}"}}</serialized_content>
  </sys_complex_object>
</record_update>`

            // Transform XML back to Fluent
            const { changedFiles } = await project.transform({
                path: 'sys_hub_flow_non_deterministic_complex_object_flow.xml',
                content: xmlContent,
            })

            expect(changedFiles).toHaveLength(1)
            const content = changedFiles[0].getContent()

            // Verify FlowObject exists
            expect(content).toContain('FlowObject({')
            expect(content).toContain('customer:')

            // Verify $id and co_type_name ARE present (non-deterministic)
            // co_type_name is NOT FDsome_variable_sys_id_123, so it should be included
            expect(content).toContain('$id:')
            expect(content).toContain("$id: 'custom_complex_object_id_from_ui'")
            expect(content).toContain('co_type_name:')
            expect(content).toContain("co_type_name: 'CustomCustomerType123'")

            // Verify fields are present
            expect(content).toContain('firstName: StringColumn')
            expect(content).toContain('lastName: StringColumn')
            expect(content).toContain('email: StringColumn')
            expect(content).toContain('age: IntegerColumn')
            expect(content).toContain('isActive: BooleanColumn')
        })
    })

    describe('Round-Trip Test: Fluent → XML → Fluent', () => {
        test('Deterministic complex object should remain deterministic after round-trip', async () => {
            const project = ctx.createProject()

            // Step 1: Fluent → XML
            const merged = await getMergedRecordUpdates(project, 'flow-complex-object-deterministic.now.ts', 'create')
            const flowVariable = merged['sys_hub_flow_variable'][0]
            const complexObject = merged['sys_complex_object'][0]
            const varSysId = flowVariable.sys_id
            const coTypeName = complexObject.name

            // Verify it's deterministic
            expect(coTypeName).toBe(`FD${varSysId}`)

            // Step 2: Create XML from merged records (simplified)
            const xmlContent = `<?xml version="1.0"?>
<record_update>
  <sys_hub_flow action="INSERT_OR_UPDATE">
    <sys_id>deterministic_complex_object_flow</sys_id>
    <name>Flow with Deterministic Complex Object</name>
  </sys_hub_flow>
  <sys_hub_flow_variable action="INSERT_OR_UPDATE">
    <sys_id>${varSysId}</sys_id>
    <element>employee</element>
    <label>Employee</label>
    <attributes>co_type_name=${coTypeName},uiType=object</attributes>
  </sys_hub_flow_variable>
  <sys_complex_object action="INSERT_OR_UPDATE">
    <sys_id>${complexObject.sys_id}</sys_id>
    <name>${coTypeName}</name>
    <namespace>FlowDesigner</namespace>
    <serialized_content>${complexObject.serialized_content}</serialized_content>
  </sys_complex_object>
</record_update>`

            // Step 3: XML → Fluent
            const { changedFiles } = await project.transform({
                path: 'sys_hub_flow_deterministic_complex_object_flow.xml',
                content: xmlContent,
            })

            const content = changedFiles[0].getContent()

            // Step 4: Verify no $id or co_type_name in generated Fluent
            const fluentLines = content.split('\n')
            const flowObjectSection = fluentLines
                .slice(fluentLines.findIndex((line) => line.includes('employee: FlowObject')))
                .slice(0, 20)
                .join('\n')

            expect(flowObjectSection).not.toContain('$id:')
            expect(flowObjectSection).not.toContain('co_type_name:')
        })

        test('Non-deterministic complex object should preserve $id and co_type_name after round-trip', async () => {
            const project = ctx.createProject()

            // Step 1: Fluent → XML
            const merged = await getMergedRecordUpdates(
                project,
                'flow-complex-object-non-deterministic.now.ts',
                'create'
            )
            const flowVariable = merged['sys_hub_flow_variable'][0]
            const complexObject = merged['sys_complex_object'][0]
            const varSysId = flowVariable.sys_id
            const coTypeName = complexObject.name

            // Verify it's NOT deterministic
            expect(coTypeName).not.toBe(`FD${varSysId}`)
            expect(coTypeName).toBe('CustomCustomerType123')
            expect(complexObject.sys_id).toBe('custom_complex_object_id_from_ui')

            // Step 2: Create XML from merged records (simplified)
            const xmlContent = `<?xml version="1.0"?>
<record_update>
  <sys_hub_flow action="INSERT_OR_UPDATE">
    <sys_id>non_deterministic_complex_object_flow</sys_id>
    <name>Flow with Non-Deterministic Complex Object</name>
  </sys_hub_flow>
  <sys_hub_flow_variable action="INSERT_OR_UPDATE">
    <sys_id>${varSysId}</sys_id>
    <element>customer</element>
    <label>Customer</label>
    <internal_type>string</internal_type>
    <attributes>co_type_name=${coTypeName},uiType=object</attributes>
  </sys_hub_flow_variable>
  <sys_complex_object action="INSERT_OR_UPDATE">
    <sys_id>${complexObject.sys_id}</sys_id>
    <name>${coTypeName}</name>
    <namespace>FlowDesigner</namespace>
    <serialized_content>${complexObject.serialized_content}</serialized_content>
  </sys_complex_object>
</record_update>`

            // Step 3: XML → Fluent
            const { changedFiles } = await project.transform({
                path: 'sys_hub_flow_non_deterministic_complex_object_flow.xml',
                content: xmlContent,
            })

            const content = changedFiles[0].getContent()

            // Step 4: Verify $id and co_type_name ARE present in generated Fluent
            const fluentLines = content.split('\n')
            const flowObjectSection = fluentLines
                .slice(fluentLines.findIndex((line) => line.includes('customer: FlowObject')))
                .slice(0, 25)
                .join('\n')

            expect(flowObjectSection).toContain('$id:')
            expect(flowObjectSection).toContain("'custom_complex_object_id_from_ui'")
            expect(flowObjectSection).toContain('co_type_name:')
            expect(flowObjectSection).toContain("'CustomCustomerType123'")
        })
    })
})
